import type { Session, User } from '@supabase/supabase-js';
import { getSupabaseClient } from './supabase-client';

/**
 * Validates the current auth session with the Supabase auth server.
 * If the session is invalid, expired, or rejected by the server,
 * automatically purges all stale tokens from storage so subsequent
 * REST requests do not fail with 401 Unauthorized.
 */
export async function validateAndGetSession(): Promise<{ user: User | null; session: Session | null }> {
  try {
    const supabase = getSupabaseClient();
    const { data, error } = await supabase.auth.getUser();

    if (error || !data?.user) {
      // Token is stale or invalid; purge local session to revert to clean anon state
      await signOutAndClearSession();
      return { user: null, session: null };
    }

    const { data: sessionData } = await supabase.auth.getSession();
    return { user: data.user, session: sessionData?.session ?? null };
  } catch (err) {
    console.warn('Session validation failed, clearing session:', err);
    await signOutAndClearSession();
    return { user: null, session: null };
  }
}

/**
 * Signs out from Supabase and thoroughly cleans up all auth tokens
 * and demo keys from localStorage and sessionStorage.
 */
export async function signOutAndClearSession(): Promise<void> {
  try {
    const supabase = getSupabaseClient();
    await supabase.auth.signOut();
  } catch (err) {
    console.warn('supabase.auth.signOut error (proceeding with manual storage wipe):', err);
  }

  if (typeof window !== 'undefined') {
    try {
      const keysToRemove: string[] = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && (key.startsWith('sb-') || key.startsWith('supabase.') || key.startsWith('rgai_demo_') || key.startsWith('rgai_review_draft:'))) {
          keysToRemove.push(key);
        }
      }
      keysToRemove.forEach((k) => localStorage.removeItem(k));

      for (let i = 0; i < sessionStorage.length; i++) {
        const key = sessionStorage.key(i);
        if (key && (key.startsWith('sb-') || key.startsWith('supabase.'))) {
          sessionStorage.removeItem(key);
        }
      }
    } catch (e) {
      console.warn('Storage purge error:', e);
    }

    // Notify all web components and test harness of logout
    window.dispatchEvent(
      new CustomEvent('rgai-auth-changed', {
        detail: { user: null, session: null },
      })
    );
  }
}
